const body = $json;

// Frontend may POST either raw address or a structured payload
let address = body.address || body.addr || '';
let price   = Number(body.purchase_price || body.price || 0) || null;
let estRent = Number(body.est_rent || body.rent || 0) || null;
const req   = body.request || { listing: true, rent_estimate: true, comps: false };

// Basic normalization
address = String(address).trim();

return [{ address, price, estRent, req }];

const g = items[0].json;
const first = (Array.isArray(g) && g.length) ? g[0] : null;
if (!first) {
  return [{ geo: null, state: null, city: null, lat: null, lon: null }];
}
const addr = first.address || {};
const state = addr.state || addr.state_code || null;
const city = addr.city || addr.town || addr.village || addr.county || null;
return [{
  geo: first,
  state,
  city,
  lat: first.lat ? Number(first.lat) : null,
  lon: first.lon ? Number(first.lon) : null
}];

const input  = $items("ParseInput")[0].json;
const geo    = $items("ParseGeocode")[0].json;
const rentE  = $items("RentEstimate")[0]?.json || null;
const rentCs = $items("RentComps")[0]?.json || [];
const saleCs = $items("SalesComps")[0]?.json || [];

// Smart defaults if provider missing
let price = input.price || null; // you can also integrate a listing price provider later
let rentEstimate = input.estRent || (rentE && (rentE.rent || rentE.estimate || rentE.monthlyRent)) || null;

// Taxes/insurance/HOA defaults (state-aware)
const state = geo.state || '';
const priceForEst = Number(price || 0);

// Conservative defaults: FL tends to have higher insurance
const defaultTaxPct = 0.015;               // 1.5% of price
const defaultInsPct = state === 'Florida' || state === 'FL' ? 0.010 : 0.005; // 1.0% in FL, else 0.5%
const defaultHOA    = 0;                    // monthly

const taxes_annual = Math.round(priceForEst ? priceForEst * defaultTaxPct : 0);
const insurance_estimate = Math.round(priceForEst ? priceForEst * defaultInsPct : 0);
const hoa_monthly = defaultHOA;

// Normalize comps (both rent & sales) to a shared schema
function normAddr(c){ return c.formattedAddress || c.address || c.fullAddress || c.streetAddress || null; }
function normNum(x){ const n = Number(x); return isNaN(n)? null : n; }

const comps = [];
(rentCs || []).forEach(c=>{
  comps.push({
    address: normAddr(c),
    beds: normNum(c.beds),
    baths: normNum(c.baths),
    sqft: normNum(c.squareFootage || c.sqft),
    type: c.propertyType || 'Rental',
    date: c.date || c.leaseDate || null,
    rent: normNum(c.rent || c.estimatedRent),
    price: null,
    ppsqft: c.squareFootage ? (Number(c.rent)/Number(c.squareFootage)) : null,
    source: 'RentCast (rental)'
  });
});
(saleCs || []).forEach(c=>{
  comps.push({
    address: normAddr(c),
    beds: normNum(c.beds),
    baths: normNum(c.baths),
    sqft: normNum(c.squareFootage || c.sqft),
    type: c.propertyType || 'Sale',
    date: c.soldDate || c.closeDate || c.date || null,
    rent: null,
    price: normNum(c.price || c.lastSalePrice),
    ppsqft: c.squareFootage ? (Number(c.price)/Number(c.squareFootage)) : null,
    source: 'RentCast (sales)'
  });
});

return [{
  listing: {
    price: price,
    taxes_annual,
    insurance_estimate,
    hoa_monthly
  },
  rent_estimate: rentEstimate,
  comps,
  meta: {
    address: input.address,
    lat: geo.lat,
    lon: geo.lon,
    city: geo.city,
    state: geo.state,
    provider_notes: 'RentCast optional; fallbacks applied when no key/data.'
  }
}];
